(function () {
'use strict';
function boot() {
var U = window.U;
var Tools = window.Tools || {};
var Result = window.ToolCore && window.ToolCore.Result;
var RV = window.ToolCore && window.ToolCore.ResultView;
if (!U || !Tools.vision || !Result || !RV) return;
var $ = function (id) { return document.getElementById(id); };
var rotations = { up: -90, right: 0, down: 90, left: 180 };
var pxPerMm = 96 / 25.4;
var calibrated = false;
var state = Tools.vision.createState();
var direction = 'up';
function showError(message) {
$('vs-error').textContent = message || '';
$('vs-error').hidden = !message;
}
function setConfigLocked(locked) {
$('vs-dist').disabled = locked;
$('vs-eye').disabled = locked;
}
function renderOpto() {
var distance = Number($('vs-dist').value);
var acuity = Tools.vision.levels[state.li];
var millimeters = Tools.vision.mmForAcuity(acuity, distance);
var theoreticalPx = millimeters * pxPerMm;
if (!isFinite(theoreticalPx) || theoreticalPx < Tools.vision.minReliablePx) {
state.finished = true;
showError('当前设备或观看距离无法可靠呈现该等级，测试已停止。');
finish();
return false;
}
$('vs-e').style.width = theoreticalPx.toFixed(2) + 'px';
$('vs-e').style.height = theoreticalPx.toFixed(2) + 'px';
$('vs-e').style.transform = 'rotate(' + rotations[direction] + 'deg)';
$('vs-level-txt').textContent = acuity.toFixed(1) + '（约 ' + millimeters.toFixed(2) + ' mm / ' + theoreticalPx.toFixed(1) + ' px）';
return true;
}
function nextDirection() {
direction = Tools.vision.randomDirection();
}
function startTest() {
if (!calibrated) {
showError('请先测量校准尺并点击“应用标定”，未完成校准不能开始测试。');
$('vs-real').focus();
return;
}
showError('');
state = Tools.vision.start(Tools.vision.createState());
nextDirection();
setConfigLocked(true);
if (!renderOpto()) return;
$('vs-result').hidden = true;
$('vs-stage').hidden = false;
}
function finish() {
setConfigLocked(false);
var score = state.maxPass;
var eyeLabels = { both: '双眼', left: '左眼', right: '右眼' };
var result = Result.create('vision', {
metrics: { maxPass: score, passedLevels: state.passedLevels.slice(), calibrated: true },
details: [
Result.detail('测试眼', eyeLabels[$('vs-eye').value] || '双眼'),
Result.detail('观看距离', $('vs-dist').selectedOptions[0].textContent),
Result.detail('已连续两次通过的等级', state.passedLevels.length ? state.passedLevels.join('、') : '无'),
Result.detail('屏幕标定', pxPerMm.toFixed(2) + ' CSS px/mm'),
],
formula: '视标高度 = 2 × 观看距离 × tan((5 / 视力等级) 角分 ÷ 2)；5 米处 1.0 视标约 7.27 mm',
assumptions: ['校准尺按 CSS 物理长度标定', '每个等级连续两次正确才记录通过', '测试在正常照明与固定距离下进行'],
source: { name: '屏幕辨向测试规则', version: '2026.11' },
precision: { acuity: 1, millimeters: 2 },
limitations: ['结果仅表示本次屏幕辨向测试表现', '屏幕亮度、像素密度、距离与环境均会影响结果', '不能替代专业验光或医学诊断'],
});
$('vs-score').textContent = score ? score.toFixed(1) : '＜0.1';
RV.renderDetails($('vs-detail'), result.details);
RV.renderExplanation($('vs-explain'), result);
$('vs-result').hidden = false;
U.track('calc_result', { tool: 'vision', resultType: score >= 1 ? 'completed-1.0' : 'completed-below-1.0' });
}
$('vs-apply').addEventListener('click', function () {
var real = U.numInput($('vs-real'));
if (!(real > 0) || real < 20 || real > 300) {
calibrated = false;
showError('请输入 20~300 mm 之间的实测长度。');
$('vs-real').focus();
return;
}
pxPerMm = $('vs-calib').offsetWidth / real;
calibrated = true;
startTest();
});
$('vsSetup').addEventListener('submit', function (event) {
event.preventDefault();
startTest();
});
U.qsa('.vs-dir .btn').forEach(function (button) {
button.addEventListener('click', function () {
if (!state.tested || state.finished) return;
var answer = Tools.vision.recordAnswer(state, button.getAttribute('data-dir') === direction);
if (!answer.changed) return;
if (state.finished || !state.tested) {
finish();
return;
}
nextDirection();
if (!renderOpto()) return;
});
});
$('vs-restart').addEventListener('click', startTest);
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})();
